mapper.select:
SELECT id, title, content, createdBy, creationDate, modifyBy, modifyDate, approvalStatus FROM tb_news
AND title LIKE CONCAT('%', #{title}, '%')
ORDER BY creationDate DESC LIMIT #{start}, #{size}

mapper.update:
UPDATE tb_news
title = #{title}, content = #{content}, modifyBy = #{modifyBy}, approvalStatus = #{approvalStatus}, modifyDate = NOW()
WHERE id = #{id}
